import { useId, useImperativeHandle, useLayoutEffect, useRef, type ComponentPropsWithRef, type ReactNode } from 'react';
import '../theme.css';
import './checkbox.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface CheckboxProps extends Omit<ComponentPropsWithRef<'input'>, 'type' | 'checked' | 'defaultChecked' | 'onChange'> {
  label: ReactNode;
  /** One line under the label. Screen readers read it after the name. */
  description?: ReactNode;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  /** Some of the items it stands for are selected. Shows a dash. */
  indeterminate?: boolean;
}

/** A choice that can be on or off, usually saved with a form. The mark draws itself when checked. */
export function Checkbox({ label, description, checked, onCheckedChange, indeterminate = false, disabled, className, ref, ...rest }: CheckboxProps) {
  const labelId = useId();
  const descriptionId = useId();
  const inner = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => inner.current as HTMLInputElement, []);

  // The mixed state exists only as a DOM property, not an attribute.
  useLayoutEffect(() => {
    if (inner.current) inner.current.indeterminate = indeterminate;
  }, [indeterminate, checked]);

  return (
    <label className={cx('ws-checkbox', className)} data-disabled={disabled ? '' : undefined}>
      <input
        {...rest}
        ref={inner}
        className="ws-checkbox__input"
        type="checkbox"
        checked={checked}
        disabled={disabled}
        aria-labelledby={labelId}
        aria-describedby={description ? descriptionId : undefined}
        onChange={(event) => {
          onCheckedChange(event.target.checked);
          // A click clears the DOM property even if the parent keeps the state.
          event.target.indeterminate = indeterminate;
        }}
      />
      <span className="ws-checkbox__box" aria-hidden="true">
        <svg viewBox="0 0 16 16" fill="none">
          <path className="ws-checkbox__check" d="M3.5 8.5l3 3 6-6.5" pathLength={1} />
          <path className="ws-checkbox__dash" d="M4 8h8" pathLength={1} />
        </svg>
      </span>
      <span className="ws-checkbox__text">
        <span className="ws-checkbox__label" id={labelId}>
          {label}
        </span>
        {description ? (
          <span className="ws-checkbox__description" id={descriptionId}>
            {description}
          </span>
        ) : null}
      </span>
    </label>
  );
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

.ws-checkbox {
  position: relative;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--ws-space-2);
  min-height: var(--ws-target-min);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
  line-height: var(--ws-leading-tight);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.ws-checkbox[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}

.ws-checkbox__input {
  position: absolute;
  top: 50%;
  left: 0;
  width: var(--ws-target-min);
  height: var(--ws-target-min);
  margin: 0;
  opacity: 0;
  transform: translateY(-50%);
  cursor: inherit;
}

.ws-checkbox__box {
  box-sizing: border-box;
  flex: none;
  pointer-events: none;
  width: 16px;
  height: 16px;
  margin-block-start: 0;
  border: 1.5px solid var(--ws-color-field-line);
  border-radius: var(--ws-radius-xs);
  background: var(--ws-color-panel);
  transition:
    background-color var(--ws-duration-fast) var(--ws-ease),
    border-color var(--ws-duration-fast) var(--ws-ease),
    transform var(--ws-duration-fast) var(--ws-ease);
}

.ws-checkbox__box svg {
  display: block;
  width: 13px;
  height: 13px;
}

.ws-checkbox__check,
.ws-checkbox__dash {
  stroke: var(--ws-color-on-accent);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset var(--ws-duration) var(--ws-ease);
}

.ws-checkbox__input:hover:not(:disabled) + .ws-checkbox__box {
  border-color: var(--ws-color-accent);
}

.ws-checkbox__input:not(:disabled):active + .ws-checkbox__box {
  transform: scale(0.92);
}

.ws-checkbox__input:checked + .ws-checkbox__box,
.ws-checkbox__input:indeterminate + .ws-checkbox__box {
  border-color: var(--ws-color-accent-hover);
  background: var(--ws-color-accent-hover);
}

.ws-checkbox__input:checked:not(:indeterminate) + .ws-checkbox__box .ws-checkbox__check,
.ws-checkbox__input:indeterminate + .ws-checkbox__box .ws-checkbox__dash {
  stroke-dashoffset: 0;
}

.ws-checkbox__input:focus-visible + .ws-checkbox__box {
  outline: var(--ws-focus-width) solid var(--ws-color-focus);
  outline-offset: var(--ws-focus-offset);
}

.ws-checkbox__text {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ws-checkbox__description {
  color: var(--ws-color-text-muted);
  font-size: var(--ws-text-sm);
  line-height: var(--ws-leading-tight);
}

@media (forced-colors: active) {
  .ws-checkbox__box {
    forced-color-adjust: none;
    border-color: CanvasText;
    background: Canvas;
  }

  .ws-checkbox__input:checked + .ws-checkbox__box,
  .ws-checkbox__input:indeterminate + .ws-checkbox__box {
    border-color: Highlight;
    background: Highlight;
  }

  .ws-checkbox__check,
  .ws-checkbox__dash {
    stroke: HighlightText;
  }
}
